-- =====================================================================
-- POKEGAMES — Itens da Red/Blue: poções, curas de estado, Revive, itens X,
-- TMs e HMs (pedido do dono em 23/10/2026).
--
-- Regras escolhidas pelo dono:
--   * na batalha (Duelos, Arena, Liga e Equipe Rocket) usar um item gasta a
--     vez, como na Red/Blue, e cada jogador usa no máximo 2 itens por batalha
--     (itens.per_battle). Itens entram antes dos ataques do turno;
--   * os itens são comprados na Loja Pokémon e às vezes achados nos baús
--     (itens.bau_pct = 25%) e na Fonte das Bolas (itens.fonte_pct = 20%);
--   * preço em moedas = preço da Red/Blue ÷ 15, a mesma conta da Great Ball
--     (600 → 40). O admin muda em Administração → Loja e PIX;
--   * TM ensina o ataque uma vez e acaba; HM nunca acaba (ensina para quantos
--     quiser). Quem aprende cada uma é igual à Red/Blue (1 a 151) e à Crystal
--     (152 a 251, só as TMs/HMs da Red/Blue);
--   * HM é RARA: não vende na loja. Sai em 1 de cada 100 baús (hm_bau_pct) ou
--     em 1 de cada 50 vitórias contra os treinadores do mapa (hm_npc_pct), e
--     cada jogador acha cada HM uma vez só. O admin também pode dar de presente;
--   * HMs abrem atalhos pequenos no tabuleiro, com equilíbrio: algumas casas
--     têm obstáculo (árvore = Cut, água = Surf, pedra = Strength, caverna
--     escura = Flash). Ao passar por uma delas com um Pokémon da equipe que
--     saiba o ataque, anda +1 casa (itens.hm.bonus), no máximo 1 atalho por
--     andada (max_per_move). Fly: 1 voo por temporada, +3 casas (fly_bonus).
--     Tudo ajustável; hm.on = false desliga os atalhos.
-- Fora da batalha a vida não muda (todos voltam inteiros), então poções e
-- curas só servem dentro da batalha. Guerras e treinadores do mapa são
-- automáticos e não usam itens.
-- Depende do 17, 18, 28, 34, 42, 43, 44 e 46. Antes de rodar, faça a cópia de segurança.
-- =====================================================================

-- ---------- catálogo ----------
create table if not exists public.pk_items (
  id      text primary key,
  name    text not null,
  kind    text not null check (kind in ('cura','estado','reviver','x','tm','hm')),
  descr   text not null default '',
  price   int not null default 0 check (price >= 0),     -- 0 = não está à venda
  move_id int references public.pk_moves(id),             -- TMs e HMs
  effect  jsonb not null default '{}'::jsonb,
  drop_w  int not null default 0,                         -- peso no sorteio dos baús e da Fonte (0 = não sai)
  sort    int not null default 0
);
create table if not exists public.pk_tm_list (
  item     text primary key,
  num      int not null,
  hm       boolean not null,
  move_id  int not null references public.pk_moves(id),
  price_rb int not null default 0
);
create table if not exists public.pk_tm_compat (
  species_id int not null references public.pokemon(id),
  move_id    int not null references public.pk_moves(id),
  primary key (species_id, move_id)
);
alter table public.pk_items enable row level security;
alter table public.pk_tm_list enable row level security;
alter table public.pk_tm_compat enable row level security;
drop policy if exists p_pki on public.pk_items;      create policy p_pki on public.pk_items for select to authenticated using (true);
drop policy if exists p_pkt on public.pk_tm_list;    create policy p_pkt on public.pk_tm_list for select to authenticated using (true);
drop policy if exists p_pkc on public.pk_tm_compat;  create policy p_pkc on public.pk_tm_compat for select to authenticated using (true);
revoke all on public.pk_items, public.pk_tm_list, public.pk_tm_compat from anon, authenticated;
grant select on public.pk_items, public.pk_tm_list, public.pk_tm_compat to authenticated;

