-- TMs (somem ao ensinar; preço da Red/Blue ÷ 15) e HMs (nunca acabam; 300 moedas)
insert into public.pk_items (id, name, kind, descr, price, move_id, drop_w, sort)
select t.item, upper(left(t.item, 2)) || lpad(t.num::text, 2, '0') || ' · ' || m.name, case when t.hm then 'hm' else 'tm' end,
       case when t.hm then 'Rara: não vende. Ensina ' || m.name || ' para quantos Pokémon quiser e abre um pequeno atalho no tabuleiro. Nunca acaba.'
            else 'Ensina ' || m.name || ' para um Pokémon. Acaba ao usar.' end,
       case when t.hm then 0 else (round(t.price_rb / 15.0 / 5) * 5)::int end, t.move_id, case when t.hm then 0 else 1 end,
       case when t.hm then 100 else 200 end + t.num
from public.pk_tm_list t join public.pk_moves m on m.id = t.move_id
on conflict (id) do update set name = excluded.name, kind = excluded.kind, descr = excluded.descr, move_id = excluded.move_id, drop_w = excluded.drop_w, sort = excluded.sort;
update public.pk_items set descr = 'Rara: não vende. Ensina Fly para quantos Pokémon quiser; uma vez por temporada ele voa com você e você anda casas a mais. Nunca acaba.' where id = 'hm02';
-- TMs de ataques que ainda não funcionam nas batalhas do Pokegames (Counter, Teleport, Mimic, Bide, Substitute):
-- ficam fora da venda e dos baús, para ninguém gastar moedas à toa (o admin pode pôr preço depois)
update public.pk_items i set descr = i.descr || ' Atenção: esse ataque ainda não funciona nas batalhas do Pokegames.', drop_w = 0,
       price = case when exists (select 1 from public.admin_audit_log a where a.action = 'preco_item_pokemon' and a.target = i.id) then i.price else 0 end
from public.pk_moves m
where i.move_id = m.id and i.kind = 'tm'
  and (m.effect in ('TRANSFORM_EFFECT','MIMIC_EFFECT','DISABLE_EFFECT','CONVERSION_EFFECT','BIDE_EFFECT','SUBSTITUTE_EFFECT','SWITCH_AND_TELEPORT_EFFECT') or m.id = 68);

-- ---------- regras (o admin pode gravar "itens" no game_config) ----------
create or replace function public.items_cfg() returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select '{"per_battle":2,"bau_pct":25,"fonte_pct":20,"hm_bau_pct":1,"hm_npc_pct":2,"hm":{"on":true,"bonus":{"CUT":1,"SURF":1,"STRENGTH":1,"FLASH":1},"max_per_move":1,"fly_bonus":3}}'::jsonb
         || coalesce(public.cfg()->'itens', '{}'::jsonb)
$$;

-- ---------- obstáculos das HMs no tabuleiro ----------
alter table public.board_nodes add column if not exists hm text;
alter table public.board_nodes drop constraint if exists board_nodes_hm_check;
alter table public.board_nodes add constraint board_nodes_hm_check check (hm is null or hm in ('CUT','SURF','STRENGTH','FLASH'));
alter table public.characters add column if not exists fly_season int;   -- temporada em que já usou o voo do Fly
-- só na primeira vez: casas comuns no meio de cada região (cerca de 1 a cada 8), com o obstáculo que combina com a região
do $$ begin
  if not exists (select 1 from public.board_nodes where hm is not null) then
    update public.board_nodes b set hm = x.hm from (
      select id, hm, row_number() over (partition by region order by id) rn, count(*) over (partition by region) n from (
        select id, region, case
          when region in ('Floresta', 'Bosque Antigo', 'Jardins Reais') then 'CUT'
          when region in ('Praia', 'Aldeia dos Pescadores', 'Cidade Portuária', 'Ponte Velha') then 'SURF'
          when region in ('Montanha', 'Desfiladeiro', 'Cratera', 'Escadaria do Trovão', 'Vale dos Ventos') then 'STRENGTH'
          when region in ('Caverna Escura', 'Atalho das Sombras', 'Bosque Enevoado', 'Mosteiro') then 'FLASH' end hm
        from public.board_nodes where kind = 'normal' and next_b is null and hunt_id is null and not hidden) y
      where hm is not null) x
    where b.id = x.id and (x.rn % 8 = 4 or (x.n < 8 and x.rn = (x.n + 1) / 2));
  end if;
end $$;

-- ---------- batalha: conferir e usar o item ----------
create or replace function public.bt_item_check(_s jsonb, _side int, _uid uuid, _item text, _t int) returns void
language plpgsql stable security definer set search_path = public, extensions as $$
declare it pk_items; T jsonb; A jsonb; ai int := (_s->'sides'->_side->>'active')::int; lim int := coalesce((public.items_cfg()->>'per_battle')::int, 2);
begin
  select * into it from pk_items where id = _item;
  if it.id is null or it.kind not in ('cura','estado','reviver','x') then raise exception 'Esse item não serve na batalha.'; end if;
  if lim <= 0 then raise exception 'Os itens estão desligados nas batalhas.'; end if;
  if coalesce((_s->'sides'->_side->>'items')::int, 0) >= lim then raise exception 'Você já usou % itens nesta batalha, que é o limite.', lim; end if;
  if coalesce((select qty from bag_items where user_id = _uid and item = _item), 0) < 1 then raise exception 'Você não tem % na bolsa.', it.name; end if;
  if _t is null or _t < 0 or _t >= jsonb_array_length(_s->'sides'->_side->'mons') then raise exception 'Escolha em qual Pokémon usar.'; end if;
  T := _s->'sides'->_side->'mons'->_t; A := _s->'sides'->_side->'mons'->ai;
  if coalesce(A->'fl'->>'charging', '') <> '' or coalesce((A->'fl'->>'recharge')::boolean, false) then
    raise exception 'Seu Pokémon está no meio de um ataque: não dá para usar item agora.';
  end if;
  if it.kind = 'reviver' then
    if (T->>'hp')::int > 0 then raise exception 'O Revive só funciona em Pokémon desmaiado.'; end if;
    return;
  end if;
  if (T->>'hp')::int <= 0 then raise exception '% desmaiou. Só o Revive funciona nele.', T->>'name'; end if;
  if it.kind = 'cura' then
    if (T->>'hp')::int >= (T->>'maxhp')::int and not (coalesce((it.effect->>'cure')::boolean, false) and T->>'status' is not null) then
      raise exception 'A vida de % já está cheia.', T->>'name';
    end if;
  elsif it.kind = 'estado' then
    if T->>'status' is null or not (it.effect->'cures' ? (T->>'status')) then raise exception 'Isso não faria efeito em % agora.', T->>'name'; end if;
  elsif it.kind = 'x' then
    if _t <> ai then raise exception 'Os itens X só valem para o Pokémon que está em campo.'; end if;
    if (T->'st'->>(it.effect->>'stat'))::int >= 6 then raise exception 'Esse atributo de % já está no máximo.', T->>'name'; end if;
  end if;
end $$;

create or replace function public.bt_item_apply(_s jsonb, _side int, _uid uuid, _item text, _t int) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare it pk_items; T jsonb := _s->'sides'->_side->'mons'->_t; ai int := (_s->'sides'->_side->>'active')::int;
  L jsonb := coalesce(_s->'_lines', '[]'::jsonb); who text := _s->'sides'->_side->>'name'; nm text := T->>'name';
  hp0 int := (T->>'hp')::int; st0 text := T->>'status'; ln jsonb; key text; left_ int;
begin
  select * into it from pk_items where id = _item;
  update bag_items set qty = qty - 1 where user_id = _uid and item = _item and qty > 0 returning qty into left_;
  if it.id is null or left_ is null or T is null then
    return jsonb_set(_s, '{_lines}', L || jsonb_build_object('txt', who || ' procurou ' || coalesce(it.name, 'um item') || ' na bolsa, mas não tinha mais.'));
  end if;
  _s := jsonb_set(_s, array['sides', _side::text, 'items'], to_jsonb(coalesce((_s->'sides'->_side->>'items')::int, 0) + 1));
  L := L || jsonb_build_object('txt', who || ' usou ' || it.name || ' em ' || nm || '.', 'side', _side, 'item', it.id);
  if it.kind = 'reviver' then
    if hp0 <= 0 then
      T := jsonb_set(jsonb_set(jsonb_set(T, '{hp}', to_jsonb(greatest(1, (T->>'maxhp')::int / 2))), '{status}', 'null'), '{sleep}', '0') #- '{fl,fainted}';
      ln := jsonb_build_object('txt', nm || ' voltou para a batalha com metade da vida!');
    end if;
  elsif hp0 <= 0 then
    ln := null;
  elsif it.kind = 'cura' then
    T := jsonb_set(T, '{hp}', to_jsonb(least((T->>'maxhp')::int, hp0 + case when it.effect->>'heal' = 'max' then (T->>'maxhp')::int else (it.effect->>'heal')::int end)));
    if coalesce((it.effect->>'cure')::boolean, false) then T := jsonb_set(jsonb_set(jsonb_set(T, '{status}', 'null'), '{sleep}', '0'), '{conf}', '0'); end if;
    ln := jsonb_build_object('txt', nm || ' recuperou ' || ((T->>'hp')::int - hp0) || ' de vida' || case when st0 is not null and T->>'status' is null then ' e ficou curado.' else '.' end);
  elsif it.kind = 'estado' then
    if st0 is not null and it.effect->'cures' ? st0 then
      T := jsonb_set(jsonb_set(T, '{status}', 'null'), '{sleep}', '0');
      ln := jsonb_build_object('txt', nm || case st0 when 'PSN' then ' não está mais envenenado.' when 'PAR' then ' não está mais paralisado.' when 'SLP' then ' acordou!'
                                                     when 'BRN' then ' não está mais queimado.' else ' descongelou!' end);
    end if;
  elsif it.kind = 'x' then
    key := it.effect->>'stat';
    if _t = ai and (T->'st'->>key)::int < 6 then
      T := jsonb_set(T, array['st', key], to_jsonb((T->'st'->>key)::int + 1));
      ln := jsonb_build_object('txt', case key when 'atk' then 'O ataque' when 'def' then 'A defesa' when 'spd' then 'A velocidade' else 'O especial' end || ' de ' || nm || ' subiu!');
    end if;
  end if;
  if ln is null then
    ln := jsonb_build_object('txt', 'Mas não fez efeito.');
  elsif _t = ai then
    ln := ln || jsonb_build_object('side', _side, 'hp', (T->>'hp')::int, 'status', T->'status');
  end if;
  _s := jsonb_set(_s, array['sides', _side::text, 'mons', _t::text], T);
  return jsonb_set(_s, '{_lines}', L || ln);
end $$;

-- ---------- achar item nos baús e na Fonte ----------
create or replace function public.item_drop(_uid uuid, _src text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare pct numeric := coalesce((public.items_cfg()->>(_src || '_pct'))::numeric, 0); it pk_items;
begin
  if random() * 100 >= pct then return null; end if;
  select * into it from pk_items where drop_w > 0 order by -ln(1 - random()) / drop_w limit 1;   -- sorteio pelo peso
  if it.id is null then return null; end if;
  insert into bag_items(user_id, item, qty) values (_uid, it.id, 1) on conflict (user_id, item) do update set qty = bag_items.qty + 1;
  return jsonb_build_object('t', 'item', 'item', it.id, 'msg', '🎒 Você também achou ' || it.name || '! Foi para a sua bolsa.');
end $$;

-- ---------- achar uma HM (raro): baús e vitórias contra treinadores do mapa ----------
create or replace function public.hm_drop(_uid uuid, _src text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare pct numeric := coalesce((public.items_cfg()->>('hm_' || _src || '_pct'))::numeric, 0); it pk_items; nm text;
begin
  if random() * 100 >= pct then return null; end if;
  -- cada HM só uma vez por jogador: sorteia entre as que ele ainda não tem
  select * into it from pk_items i where i.kind = 'hm'
     and not exists (select 1 from bag_items b where b.user_id = _uid and b.item = i.id and b.qty > 0) order by random() limit 1;
  if it.id is null then return null; end if;
  insert into bag_items(user_id, item, qty) values (_uid, it.id, 1) on conflict (user_id, item) do update set qty = 1;
  select name into nm from characters where user_id = _uid;
  insert into event_log(user_id, kind, message) values (_uid, 'hm', '✨ ' || nm || ' achou a rara ' || it.name || '!');
  return jsonb_build_object('t', 'item', 'item', it.id, 'msg', '✨ Que sorte! Você achou a rara ' || it.name || '! Ela nunca acaba: ensine na coleção (📀 Ensinar TM/HM).');
end $$;

-- ---------- atalhos das HMs (chamado pelo do_move depois de andar) ----------
create or replace function public.hm_shortcut(_cid uuid, _path0 int) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare me characters; hc jsonb := public.items_cfg()->'hm'; team int[]; passed int[]; n record; steps int := 0; ev jsonb := '[]'::jsonb;
  tip boolean := false; mv int; b int; used int := 0; maxu int := coalesce((public.items_cfg()->'hm'->>'max_per_move')::int, 1);
  fb int := coalesce((public.items_cfg()->'hm'->>'fly_bonus')::int, 0); season int := coalesce((select max(id) from seasons), 0);
begin
  if not coalesce((hc->>'on')::boolean, true) then return '{"steps": 0}'::jsonb; end if;
  select * into me from characters where id = _cid;
  select coalesce(array_agg(distinct x), '{}') into team from monsters m, unnest(m.moves) x where m.user_id = me.user_id and m.team_slot is not null;
  passed := me.path[_path0 + 1 : coalesce(array_length(me.path, 1), 0)];
  for n in select bn.id, bn.hm from board_nodes bn join unnest(passed) with ordinality u(id, ord) on u.id = bn.id where bn.hm is not null order by u.ord loop
    mv := case n.hm when 'CUT' then 15 when 'SURF' then 57 when 'STRENGTH' then 70 else 148 end;
    b := coalesce((hc->'bonus'->>n.hm)::int, 0);
    if mv = any(team) and b > 0 and used < maxu then
      steps := steps + b; used := used + 1;
      ev := ev || jsonb_build_object('t', 'hm', 'hm', n.hm, 'msg', case n.hm when 'CUT' then '🌳 Cut: seu Pokémon cortou a árvore e abriu um atalho'
          when 'SURF' then '🌊 Surf: seu Pokémon atravessou a água nadando com você' when 'STRENGTH' then '💪 Strength: seu Pokémon empurrou a pedra do caminho'
          else '💡 Flash: seu Pokémon iluminou a caverna e achou um atalho' end || ' (+' || b || ' casas).');
    elsif not tip and b > 0 and not (mv = any(team)) then
      tip := true;
      ev := ev || jsonb_build_object('t', 'hm', 'hm', n.hm, 'msg', 'Você passou por ' || case n.hm when 'CUT' then 'uma árvore no caminho. Com um Pokémon que saiba Cut'
          when 'SURF' then 'uma passagem pela água. Com um Pokémon que saiba Surf' when 'STRENGTH' then 'uma pedra grande. Com um Pokémon que saiba Strength'
          else 'uma caverna escura. Com um Pokémon que saiba Flash' end || ' na equipe, teria pego um atalho.');
    end if;
  end loop;
  -- Fly: uma vez por temporada, voa algumas casas a mais
  if 19 = any(team) and fb > 0 and coalesce(me.fly_season, 0) < season then
    steps := steps + fb;
    update characters set fly_season = season where id = _cid;
    ev := ev || jsonb_build_object('t', 'hm', 'hm', 'FLY', 'msg', '🕊️ Fly: seu Pokémon voou com você (+' || fb || ' casas). É o voo desta temporada: o próximo só na temporada que vem.');
  end if;
  return jsonb_build_object('steps', steps, 'ev', ev);
end $$;

-- ---------- ensinar TM/HM ----------
create or replace function public.mon_teach(_mon uuid, _item text, _forget int default null) returns public.monsters
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); m monsters; t pk_tm_list; mv pk_moves;
begin
  select * into m from monsters where id = _mon and user_id = uid for update;
  if m.id is null then raise exception 'Esse Pokémon não é seu.'; end if;
  select * into t from pk_tm_list where item = _item;
  if t.item is null then raise exception 'Isso não é uma TM nem uma HM.'; end if;
  select * into mv from pk_moves where id = t.move_id;
  if coalesce((select qty from bag_items where user_id = uid and item = _item for update), 0) < 1 then raise exception 'Você não tem essa % na bolsa.', upper(left(_item, 2)); end if;
  if not exists (select 1 from pk_tm_compat where species_id = m.species_id and move_id = t.move_id) then
    raise exception '% não consegue aprender %.', (select name from pokemon where id = m.species_id), mv.name;
  end if;
  if t.move_id = any(m.moves) then raise exception 'Esse Pokémon já sabe %.', mv.name; end if;
  if cardinality(m.moves) < 4 then
    m.moves := m.moves || t.move_id;
  else
    if _forget is null or _forget < 1 or _forget > cardinality(m.moves) then raise exception 'Escolha um ataque para esquecer.'; end if;
    m.moves[_forget] := t.move_id;
  end if;
  update monsters set moves = m.moves, pending_moves = array_remove(pending_moves, t.move_id) where id = m.id returning * into m;
  if not t.hm then update bag_items set qty = qty - 1 where user_id = uid and item = _item; end if;
  insert into mon_events(user_id, mon_id, kind, data, seen) values (uid, m.id, 'golpe', jsonb_build_object('species', m.species_id, 'move', t.move_id, 'learned', true, 'item', _item), true);
  return m;
end $$;

-- ---------- admin: preço dos itens Pokémon ----------
create or replace function public.admin_pk_item_set(_id text, _price int) returns public.pk_items
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); it pk_items; nw pk_items;
begin
  if not public.has_role(uid, 'admin') then raise exception 'Só o administrador muda preços.'; end if;
  select * into it from pk_items where id = _id for update;
  if it.id is null then raise exception 'Item inexistente.'; end if;
  if _price is null or _price < 0 or _price > 1000000 then raise exception 'Preço em moedas inválido (0 = não vende).'; end if;
  update pk_items set price = _price where id = _id returning * into nw;
  insert into admin_audit_log(admin_id, action, target, before, after) values (uid, 'preco_item_pokemon', _id, jsonb_build_object('price', it.price), jsonb_build_object('price', nw.price));
  return nw;
end $$;

-- presentes do admin também podem dar os itens novos
create or replace function public.gift_bag_ok(_ref text) returns boolean
language sql stable security definer set search_path = public, extensions as $$
  select public.pix_bag_ok(_ref) or _ref in ('pedra_sol','pedra_lua_nova','pedra_metal','pedra_rei') or exists (select 1 from public.pk_items where id = _ref)
$$;

-- ---------- ação "item" na batalha ----------
alter table public.battle_actions add column if not exists item text;
alter table public.battle_actions drop constraint if exists battle_actions_kind_check;
alter table public.battle_actions add constraint battle_actions_kind_check check (kind in ('move','switch','forced','item'));
drop function if exists public.battle_act(uuid, int, text, int);

-- motor: resolve um turno (versão do 18 + itens da bolsa)
create or replace function public.bt_resolve(_id uuid) returns void
language plpgsql security definer set search_path = public, extensions as $$
declare b battles; s jsonb; lines jsonb := '[]'::jsonb; act record; acts jsonb := '{}'::jsonb; order_ int[]; side int; ds int; A jsonb; D jsonb; ai int;
  mid int; slot int; pr0 int; pr1 int; sp0 numeric; sp1 numeric; alive0 int; alive1 int; i int; m jsonb; dmg int; xp int; winner uuid; reason text;
  c jsonb := public.pk_cfg(); first_done boolean := false; nm text;
begin
  select * into b from battles where id = _id for update;
  s := b.state;
  for act in select * from battle_actions where battle_id = b.id and turn = b.turn loop
    acts := acts || jsonb_build_object(act.side::text, jsonb_build_object('kind', act.kind, 'value', act.value, 'item', act.item, 'uid', act.user_id));
  end loop;
  -- trocas primeiro (inclusive as trocas obrigatórias depois de um nocaute)
  for side in 0 .. 1 loop
    if acts->side::text->>'kind' = 'switch' then
      ai := (s->'sides'->side->>'active')::int; A := s->'sides'->side->'mons'->ai;
      if (A->>'hp')::int > 0 then lines := lines || jsonb_build_object('txt', (s->'sides'->side->>'name') || ' chamou ' || (A->>'name') || ' de volta.'); end if;
      -- ao sair, perde mudanças de atributo, confusão, semente, tela e preparo
      A := jsonb_set(jsonb_set(A, '{st}', '{"atk":0,"def":0,"spd":0,"spc":0,"acc":0,"eva":0}'), '{conf}', '0');
      A := jsonb_set(A, '{fl}', '{}');
      s := jsonb_set(s, array['sides', side::text, 'mons', ai::text], A);
      s := jsonb_set(s, array['sides', side::text, 'active'], to_jsonb((acts->side::text->>'value')::int));
      s := jsonb_set(s, array['sides', side::text, 'need_switch'], 'false');
      lines := lines || jsonb_build_object('txt', (s->'sides'->side->>'name') || ' mandou ' || (s->'sides'->side->'mons'->((acts->side::text->>'value')::int)->>'name') || '!', 'side', side, 'switch', (acts->side::text->>'value')::int);
    elsif acts->side::text->>'kind' = 'item' then
      -- itens da bolsa (arquivo 47): usados antes dos ataques, como na Red/Blue
      s := public.bt_item_apply(jsonb_set(s, '{_lines}', lines), side, (acts->side::text->>'uid')::uuid, acts->side::text->>'item', (acts->side::text->>'value')::int);
      lines := s->'_lines'; s := s - '_lines';
    end if;
  end loop;
  if b.phase = 'troca' then
    update battles set state = s, phase = 'normal', turn = turn + 1, ready1 = false, ready2 = false,
           deadline = now() + make_interval(hours => (c->'battle'->>'turn_hours')::int),
           log = log || jsonb_build_array(jsonb_build_object('turn', b.turn, 'lines', lines)) where id = b.id;
    return;
  end if;
  -- ordem dos ataques: prioridade (Quick Attack) e velocidade
  pr0 := case when acts->'0'->>'kind' = 'move' and (select code from pk_moves where id = (s->'sides'->0->'mons'->((s->'sides'->0->>'active')::int)->'moves'->((acts->'0'->>'value')::int)->>'id')::int) = 'QUICK_ATTACK' then 1 else 0 end;
  pr1 := case when acts->'1'->>'kind' = 'move' and (select code from pk_moves where id = (s->'sides'->1->'mons'->((s->'sides'->1->>'active')::int)->'moves'->((acts->'1'->>'value')::int)->>'id')::int) = 'QUICK_ATTACK' then 1 else 0 end;
  sp0 := public.bt_speed(s->'sides'->0->'mons'->((s->'sides'->0->>'active')::int));
  sp1 := public.bt_speed(s->'sides'->1->'mons'->((s->'sides'->1->>'active')::int));
  order_ := case when pr0 > pr1 or (pr0 = pr1 and (sp0 > sp1 or (sp0 = sp1 and random() < 0.5))) then array[0, 1] else array[1, 0] end;
  foreach side in array order_ loop
    ds := 1 - side;
    continue when acts->side::text->>'kind' in ('switch', 'item');
    ai := (s->'sides'->side->>'active')::int; A := s->'sides'->side->'mons'->ai;
    continue when (A->>'hp')::int <= 0;
    continue when (s->'sides'->ds->'mons'->((s->'sides'->ds->>'active')::int)->>'hp')::int <= 0;
    s := public.bt_can_act(jsonb_set(s, '{_lines}', lines), side); lines := s->'_lines'; s := s - '_lines';
    if not (s->>'blocked')::boolean then
      A := s->'sides'->side->'mons'->ai;
      if coalesce(A->'fl'->>'charging', '') <> '' then mid := (A->'fl'->>'charging')::int;   -- segundo turno do ataque de dois turnos
      elsif acts->side::text->>'kind' = 'forced' or (acts->side::text->>'value')::int < 0 then mid := 165;  -- Struggle
      else
        slot := (acts->side::text->>'value')::int; mid := (A->'moves'->slot->>'id')::int;
        s := jsonb_set(s, array['sides', side::text, 'mons', ai::text, 'moves', slot::text, 'pp'], to_jsonb(greatest(0, (A->'moves'->slot->>'pp')::int - 1)));
      end if;
      s := public.bt_use_move(jsonb_set(s, '{_lines}', lines), side, mid, not first_done); lines := s->'_lines'; s := s - '_lines';
    end if;
    s := s - 'blocked';
    first_done := true;
    -- nocautes depois de cada ação (XP para quem derrubou)
    for i in 0 .. 1 loop
      m := s->'sides'->i->'mons'->((s->'sides'->i->>'active')::int);
      if (m->>'hp')::int <= 0 and not coalesce((m->'fl'->>'fainted')::boolean, false) then
        s := jsonb_set(s, array['sides', i::text, 'mons', (s->'sides'->i->>'active'), 'fl', 'fainted'], 'true');
        lines := lines || jsonb_build_object('txt', (m->>'name') || ' desmaiou!', 'side', i, 'faint', true);
        A := s->'sides'->(1 - i)->'mons'->((s->'sides'->(1 - i)->>'active')::int);
        if (A->>'hp')::int > 0 then
          xp := floor(floor((m->>'bexp')::int * (m->>'level')::int / 7.0) * (c->'xp'->>'battle_mult')::numeric);
          s := jsonb_set(s, array['xp', A->>'id'], to_jsonb(coalesce((s->'xp'->>(A->>'id'))::int, 0) + xp));
        end if;
      end if;
    end loop;
  end loop;
  -- dano no fim do turno: veneno, queimadura e semente (1/16 da vida)
  for side in 0 .. 1 loop
    ai := (s->'sides'->side->>'active')::int; A := s->'sides'->side->'mons'->ai; nm := A->>'name';
    continue when (A->>'hp')::int <= 0;
    A := A #- '{fl,flinch}';
    if A->>'status' in ('PSN','BRN') then
      dmg := greatest(1, (A->>'maxhp')::int / 16); A := jsonb_set(A, '{hp}', to_jsonb(greatest(0, (A->>'hp')::int - dmg)));
      lines := lines || jsonb_build_object('txt', nm || case when A->>'status' = 'PSN' then ' sofre com o veneno.' else ' sofre com a queimadura.' end, 'side', side, 'hp', (A->>'hp')::int);
    end if;
    if coalesce((A->'fl'->>'leech')::boolean, false) and (A->>'hp')::int > 0 then
      dmg := least((A->>'hp')::int, greatest(1, (A->>'maxhp')::int / 16)); A := jsonb_set(A, '{hp}', to_jsonb((A->>'hp')::int - dmg));
      lines := lines || jsonb_build_object('txt', 'A semente sugou a vida de ' || nm || '!', 'side', side, 'hp', (A->>'hp')::int);
      D := s->'sides'->(1 - side)->'mons'->((s->'sides'->(1 - side)->>'active')::int);
      if (D->>'hp')::int > 0 then
        D := jsonb_set(D, '{hp}', to_jsonb(least((D->>'maxhp')::int, (D->>'hp')::int + dmg)));
        s := jsonb_set(s, array['sides', (1 - side)::text, 'mons', (s->'sides'->(1 - side)->>'active')], D);
        lines := lines || jsonb_build_object('txt', (D->>'name') || ' recuperou vida.', 'side', 1 - side, 'hp', (D->>'hp')::int);
      end if;
    end if;
    s := jsonb_set(s, array['sides', side::text, 'mons', ai::text], A);
    if (A->>'hp')::int <= 0 then
      s := jsonb_set(s, array['sides', side::text, 'mons', ai::text, 'fl', 'fainted'], 'true');
      lines := lines || jsonb_build_object('txt', nm || ' desmaiou!', 'side', side, 'faint', true);
      D := s->'sides'->(1 - side)->'mons'->((s->'sides'->(1 - side)->>'active')::int);
      if (D->>'hp')::int > 0 then
        xp := floor(floor((A->>'bexp')::int * (A->>'level')::int / 7.0) * (c->'xp'->>'battle_mult')::numeric);
        s := jsonb_set(s, array['xp', D->>'id'], to_jsonb(coalesce((s->'xp'->>(D->>'id'))::int, 0) + xp));
      end if;
    end if;
  end loop;
  -- fim de jogo?
  select count(*) filter (where (x->>'hp')::int > 0) into alive0 from jsonb_array_elements(s->'sides'->0->'mons') x;
  select count(*) filter (where (x->>'hp')::int > 0) into alive1 from jsonb_array_elements(s->'sides'->1->'mons') x;
  update battles set state = s, log = log || jsonb_build_array(jsonb_build_object('turn', b.turn, 'lines', lines)) where id = b.id;
  if alive0 = 0 or alive1 = 0 then
    winner := case when alive0 = 0 and alive1 = 0 then null when alive0 = 0 then b.p2 else b.p1 end;
    reason := case when winner is null then 'empate' else 'nocaute' end;
    perform public.bt_finish(b.id, winner, reason);
    return;
  end if;
  -- quem ficou sem Pokémon em campo precisa trocar
  for side in 0 .. 1 loop
    if (s->'sides'->side->'mons'->((s->'sides'->side->>'active')::int)->>'hp')::int <= 0 then
      s := jsonb_set(s, array['sides', side::text, 'need_switch'], 'true');
    end if;
  end loop;
  if coalesce((s->'sides'->0->>'need_switch')::boolean, false) or coalesce((s->'sides'->1->>'need_switch')::boolean, false) then
    update battles set state = s, phase = 'troca', turn = turn + 1,
           ready1 = not coalesce((s->'sides'->0->>'need_switch')::boolean, false), ready2 = not coalesce((s->'sides'->1->>'need_switch')::boolean, false),
           deadline = now() + make_interval(hours => (c->'battle'->>'turn_hours')::int) where id = b.id;
  else
    update battles set state = s, turn = turn + 1, ready1 = false, ready2 = false,
           deadline = now() + make_interval(hours => (c->'battle'->>'turn_hours')::int) where id = b.id;
  end if;
end $$;

-- ação do turno (versão do 44 + 'item': usar um item da bolsa, gasta a vez)
create or replace function public.battle_act(_id uuid, _turn int, _kind text, _value int, _item text default null) returns public.battles
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); b battles; side int; s jsonb; A jsonb; kind text := _kind; ok boolean; pre int; p jsonb; k int; item text;
begin
  select * into b from battles where id = _id for update;
  if b.id is null or uid not in (b.p1, b.p2) then raise exception 'Batalha não encontrada.'; end if;
  if b.status <> 'ativa' then raise exception 'Essa batalha não está em andamento.'; end if;
  side := case when uid = b.p1 then 0 else 1 end;
  if _kind = 'forfeit' then
    update battles set log = log || jsonb_build_array(jsonb_build_object('turn', b.turn, 'lines', jsonb_build_array(jsonb_build_object('txt', (b.state->'sides'->side->>'name') || ' desistiu da batalha.'))))
     where id = b.id;
    perform public.bt_finish(b.id, case when side = 0 then b.p2 else b.p1 end, 'desistencia');
    if b.mode = 'rocket' then perform public.rocket_after(b.id, public.rocket_dmg(b.state)); end if;
    select * into b from battles where id = _id; return b;
  end if;
  if _turn <> b.turn then raise exception 'Esse turno já passou. Atualize a tela.'; end if;
  if (side = 0 and b.ready1) or (side = 1 and b.ready2) then raise exception 'Você já escolheu a ação deste turno. Espere o adversário.'; end if;
  s := b.state; A := s->'sides'->side->'mons'->((s->'sides'->side->>'active')::int);
  if b.phase = 'troca' or coalesce((s->'sides'->side->>'need_switch')::boolean, false) then
    if _kind <> 'switch' then raise exception 'Escolha qual Pokémon vai entrar.'; end if;
  end if;
  if _kind = 'switch' then
    if _value is null or _value < 0 or _value >= jsonb_array_length(s->'sides'->side->'mons') then raise exception 'Pokémon inválido.'; end if;
    if _value = (s->'sides'->side->>'active')::int then raise exception 'Esse Pokémon já está em campo.'; end if;
    if (s->'sides'->side->'mons'->_value->>'hp')::int <= 0 then raise exception 'Esse Pokémon desmaiou.'; end if;
    if (A->>'hp')::int > 0 and b.phase <> 'troca' and (coalesce(A->'fl'->>'charging', '') <> '' or coalesce((A->'fl'->>'recharge')::boolean, false)) then raise exception 'Não dá para trocar agora.'; end if;
  elsif _kind = 'move' then
    if coalesce(A->'fl'->>'charging', '') <> '' or coalesce((A->'fl'->>'recharge')::boolean, false) then kind := 'forced';
    elsif _value = -1 then
      select bool_and((x->>'pp')::int = 0) into ok from jsonb_array_elements(A->'moves') x;
      if not ok then raise exception 'Ainda há ataques com PP.'; end if;
    else
      if _value is null or _value < 0 or _value >= jsonb_array_length(A->'moves') then raise exception 'Ataque inválido.'; end if;
      if (A->'moves'->_value->>'pp')::int <= 0 then raise exception 'Esse ataque está sem PP.'; end if;
    end if;
  elsif _kind = 'item' then
    perform public.bt_item_check(s, side, uid, _item, _value);
    item := _item;
  else raise exception 'Ação inválida.'; end if;
  insert into battle_actions(battle_id, turn, side, user_id, kind, value, item) values (b.id, b.turn, side, uid, kind, _value, item);
  -- Equipe Rocket (arquivo 44): o servidor joga pelo lado da Rocket na hora e conta o dano na barra coletiva
  if b.mode = 'rocket' then
    pre := public.rocket_dmg(b.state);
    p := public.war_pick(b.state, 1, 'forte');
    insert into battle_actions(battle_id, turn, side, user_id, kind, value) values (b.id, b.turn, 1, uid, p->>'kind', (p->>'value')::int);
    perform public.bt_resolve(b.id);
    for k in 1 .. 3 loop
      select * into b from battles where id = _id;
      exit when b.status <> 'ativa' or b.phase <> 'troca' or not coalesce((b.state->'sides'->1->>'need_switch')::boolean, false);
      insert into battle_actions(battle_id, turn, side, user_id, kind, value) values (b.id, b.turn, 1, uid, 'switch', public.war_switch(b.state, 1, true));
      perform public.bt_resolve(b.id);
    end loop;
    perform public.rocket_after(_id, pre);
    select * into b from battles where id = _id;
    return b;
  end if;
  if side = 0 then update battles set ready1 = true where id = b.id returning * into b;
  else update battles set ready2 = true where id = b.id returning * into b; end if;
  if b.ready1 and b.ready2 then perform public.bt_resolve(b.id); end if;
  select * into b from battles where id = _id;
  return b;
end $$;

-- compra na Loja Pokémon (versão do 28 + itens do arquivo 47)
create or replace function public.pk_buy(_item text, _qty int default 1) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare uid uuid := public.assert_active(); c jsonb := public.pk_cfg(); price int; me characters; it pk_items;
begin
  if _qty is null or _qty < 1 or _qty > 20 then raise exception 'Quantidade inválida.'; end if;
  if _item like '%\_ball' and c->'capture'->'balls' ? replace(_item, '_ball', '') then price := (c->'capture'->'balls'->replace(_item, '_ball', '')->>'price')::int;
  elsif _item in ('pedra_fogo','pedra_agua','pedra_trovao','pedra_folha','pedra_lua')
     or (public.gen2_on() and _item in ('pedra_sol','pedra_lua_nova','pedra_metal','pedra_rei')) then price := (c->'stones'->>'price')::int;
  else
    -- itens da Red/Blue (arquivo 47): poções, curas, X, TMs e HMs
    select * into it from pk_items where id = _item;
    if it.id is null then raise exception 'Item inválido.'; end if;
    if it.price <= 0 then raise exception 'Esse item não está à venda.'; end if;
    if it.kind = 'hm' then
      if _qty <> 1 then raise exception 'A HM nunca acaba: compre só uma.'; end if;
      if exists (select 1 from bag_items where user_id = uid and item = _item and qty > 0) then raise exception 'Você já tem essa HM. Ela não acaba.'; end if;
    end if;
    price := it.price;
  end if;
  if price <= 0 then raise exception 'Esse item é grátis.'; end if;
  select * into me from characters where user_id = uid for update;
  if me.coins < price * _qty then raise exception 'Moedas insuficientes.'; end if;
  update characters set coins = coins - price * _qty where id = me.id;
  insert into bag_items(user_id, item, qty) values (uid, _item, _qty) on conflict (user_id, item) do update set qty = bag_items.qty + _qty;
  return jsonb_build_object('item', _item, 'qty', (select qty from bag_items where user_id = uid and item = _item), 'coins', me.coins - price * _qty);
end $$;

-- andar no dia (versão do 46 + atalhos das HMs e itens nos baús)
create or replace function public.do_move(_d date, _recovery boolean) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  uid uuid := auth.uid(); c jsonb := public.cfg(); today date := public.game_today();
  me characters; other characters; nd board_nodes; tr traps; w jsonb; x record;
  m public.puzzle_mode; s guess_sessions; st int; modes jsonb := '{}'::jsonb;
  base int := 0; roll int; r2 int; i int; bonus int; skill_steps int := 0; total int; from_node int; landed int; path0 int;
  ev jsonb := '[]'::jsonb; sal int := 0; extra_coins int := 0; extra_xp int := 0; cls text; sv int; skill_on boolean; dodge boolean := false;
  card int; chance int; steal int; my_dist int; tmp_node int; tmp_path int[]; msg text; amt int;
  xp_gain int; coin_gain int; new_level int; old_level int;
  leader uuid; prop properties; toll int; bounty int := coalesce((public.cfg()->>'bounty_coins')::int, 60);
  boss world_bosses; mud int; passed int[]; champ uuid; hx jsonb;
begin
  perform public.settle();
  leader := public.leader_id(); champ := public.round_champion();
  select * into me from characters where user_id = uid for update;
  if me.id is null then raise exception 'Crie seu personagem primeiro.'; end if;
  if exists (select 1 from daily_moves where user_id = uid and move_date = _d) then raise exception 'Você já andou nesse dia.'; end if;
  old_level := me.level; cls := me.class::text;
  skill_on := not _recovery and me.skill_date = today;
  sv := public.skill_value(cls, me.level);

  foreach m in array enum_range(null::public.puzzle_mode) loop
    s := null;
    select * into s from guess_sessions where user_id = uid and puzzle_date = _d and mode = m;
    st := public.mode_steps(coalesce(s.attempts,0), coalesce(s.solved,false));
    base := base + st;
    modes := modes || jsonb_build_object(m::text, jsonb_build_object('attempts', coalesce(s.attempts,0), 'solved', coalesce(s.solved,false), 'steps', st));
  end loop;

  roll := (c->>'roll_min')::int + floor(random() * ((c->>'roll_max')::int - (c->>'roll_min')::int + 1))::int;
  if skill_on and cls = 'arqueiro' then
    for i in 2..greatest(sv,2) loop
      r2 := (c->>'roll_min')::int + floor(random() * ((c->>'roll_max')::int - (c->>'roll_min')::int + 1))::int;
      roll := greatest(roll, r2);
    end loop;
    ev := ev || jsonb_build_object('t','habilidade','msg','Tiro certeiro: a roleta girou ' || greatest(sv,2) || ' vezes e ficou com ' || roll || '.');
  end if;
  if cls = 'arqueiro' and roll < (c->>'arqueiro_min_die')::int then
    roll := (c->>'arqueiro_min_die')::int;
    ev := ev || jsonb_build_object('t','arqueiro','msg','Olho de arqueiro: a roleta vale no mínimo ' || roll || '.');
  end if;
  if skill_on and cls = 'domador' then
    roll := roll * greatest(sv,2);
    ev := ev || jsonb_build_object('t','habilidade','msg','Montaria: a roleta valeu ' || greatest(sv,2) || ' vezes mais (' || roll || ').');
  end if;
  if skill_on and cls in ('guerreiro','ladino','clerigo') and sv > 0 then
    skill_steps := sv;
    ev := ev || jsonb_build_object('t','habilidade','msg',
      case cls when 'guerreiro' then 'Investida' when 'ladino' then 'Atalho' else 'Bênção' end || ': +' || sv || ' casas.');
  end if;
  if skill_on and cls = 'mago' then
    skill_steps := public.next_good_steps(me.id, sv);
    ev := ev || jsonb_build_object('t','habilidade','msg', case when skill_steps > 0 then 'Teleporte: saltou ' || skill_steps || ' casas até uma casa especial.' else 'Teleporte: nenhuma casa especial ao alcance.' end);
  end if;
  if skill_on and cls = 'ladino' then dodge := true; end if;
  if skill_on and cls = 'clerigo' then ev := ev || jsonb_build_object('t','habilidade','msg','Bênção ativa: nada te empurra para trás hoje.'); end if;

  bonus := me.bonus_steps;
  total := base + roll + bonus + skill_steps;
  -- lama da catapulta de um rival
  mud := coalesce(me.pending_mud, 0);
  if mud > 0 and not _recovery then
    update characters set pending_mud = 0 where id = me.id;
    if public.is_shielded(me.id) then
      ev := ev || jsonb_build_object('t','lama','msg','Atiraram lama em você, mas a Bênção te protegeu.');
    else
      total := greatest(0, total - mud);
      ev := ev || jsonb_build_object('t','lama','msg','Lama da catapulta: você perdeu ' || mud || ' casas nesta andada.');
    end if;
  end if;
  from_node := me.node;

  if me.arrived_rank is not null then
    ev := ev || jsonb_build_object('t','castelo','msg','Você já está no Castelo. Continue jogando para ganhar moedas, XP e vencer rodadas.');
    total := 0;
  else
    update characters set bonus_steps = 0 where id = me.id;
    path0 := coalesce(array_length(me.path,1),1);
    w := public.walk(me.id, total);
    sal := sal + (w->>'salary')::int;
    landed := (w->>'node')::int;

    -- atalhos das HMs (arquivo 47): Cut, Surf, Strength e Flash nas casas com obstáculo; Fly de tempos em tempos
    hx := public.hm_shortcut(me.id, path0);
    ev := ev || coalesce(hx->'ev', '[]'::jsonb);
    if coalesce((hx->>'steps')::int, 0) > 0 then
      w := public.walk(me.id, (hx->>'steps')::int); sal := sal + (w->>'salary')::int;
      landed := (w->>'node')::int;
    end if;

    -- encontro com o lendário (passando ou parando)
    select * into boss from world_bosses where status = 'ativo' order by id desc limit 1;
    if boss.id is not null then
      passed := (select path from characters where id = me.id)[path0 : coalesce(array_length((select path from characters where id = me.id),1),1)];
      if boss.node = any(passed) and not exists (select 1 from boss_contacts bc where bc.boss_id = boss.id and bc.user_id = uid) then
        insert into boss_contacts(boss_id, user_id) values (boss.id, uid);
        ev := ev || jsonb_build_object('t','lendario','msg','Você encontrou o lendário ' || (select name from pokemon where id = boss.pokemon_id) || '! Agora pode atacá-lo pelo painel.');
      end if;
    end if;

    -- Ladino: pega moedas de quem ultrapassa
    if cls = 'ladino' then
      amt := public.passive_value('ladino', me.level);
      for x in
        select ch.id, ch.name, ch.coins from characters ch
        where ch.user_id <> uid and ch.arrived_rank is null
          and ch.node = any ((select path from characters where id = me.id)[path0 + 1 : coalesce(array_length((select path from characters where id = me.id),1),1) - 1])
        for update
      loop
        steal := least(amt, x.coins);
        if steal > 0 then
          update characters set coins = coins - steal where id = x.id;
          extra_coins := extra_coins + steal;
          ev := ev || jsonb_build_object('t','ladino','msg','Mão leve: pegou ' || steal || ' moedas de ' || x.name || ' ao passar.');
        end if;
      end loop;
    end if;

    -- 1) armadilha de outro jogador
    select * into tr from traps where node = landed and triggered_at is null and owner_id <> uid for update;
    if tr.id is not null then
      update traps set triggered_by = uid, triggered_at = now() where id = tr.id;
      select * into other from characters where user_id = tr.owner_id;
      if dodge then
        ev := ev || jsonb_build_object('t','armadilha','msg','Atalho: você desviou da armadilha de ' || other.name || '.');
      elsif cls = 'mago' and random() * 100 < (c->>'mago_resist_pct')::int then
        ev := ev || jsonb_build_object('t','armadilha','msg','Você desfez com magia a armadilha de ' || other.name || '.');
      elsif public.is_shielded(me.id) then
        ev := ev || jsonb_build_object('t','armadilha','msg','A Bênção te protegeu da armadilha de ' || other.name || '.');
      else
        perform public.go_back(me.id, (c->>'trap_push')::int);
        update characters set coins = coins + (c->>'trap_reward')::int where user_id = tr.owner_id;
        ev := ev || jsonb_build_object('t','armadilha','msg','Você caiu na armadilha de ' || other.name || ' e voltou ' || (c->>'trap_push') || ' casas.');
        insert into event_log(user_id, kind, message) values (uid, 'armadilha', me.name || ' caiu na armadilha de ' || other.name || '.');
      end if;
    else
      -- 2) efeito da casa
      select * into nd from board_nodes where id = landed;
      if nd.kind = 'avanco' then
        w := public.walk(me.id, nd.value); sal := sal + (w->>'salary')::int;
        ev := ev || jsonb_build_object('t','avanco','msg','Vento a favor! Avançou mais ' || nd.value || ' casas.');
      elsif nd.kind = 'recuo' then
        if dodge then ev := ev || jsonb_build_object('t','recuo','msg','Atalho: você contornou o lamaçal.');
        elsif public.is_shielded(me.id) then ev := ev || jsonb_build_object('t','recuo','msg','A Bênção te segurou no lamaçal.');
        elsif cls = 'mago' and random() * 100 < (c->>'mago_resist_pct')::int then ev := ev || jsonb_build_object('t','recuo','msg','Escorregou, mas a magia segurou você no lugar.');
        else perform public.go_back(me.id, nd.value); ev := ev || jsonb_build_object('t','recuo','msg','Lamaçal! Voltou ' || nd.value || ' casas.');
        end if;
      elsif nd.kind = 'bau' then
        extra_coins := extra_coins + (c->>'chest_coins')::int;
        ev := ev || jsonb_build_object('t','bau','msg','Achou um baú com ' || (c->>'chest_coins') || ' moedas.');
        hx := public.item_drop(uid, 'bau');
        if hx is not null then ev := ev || hx; end if;
        hx := public.hm_drop(uid, 'bau');
        if hx is not null then ev := ev || hx; end if;
      elsif nd.kind = 'xp' then
        extra_xp := extra_xp + (c->>'xp_square')::int;
        ev := ev || jsonb_build_object('t','xp','msg','Treino na clareira: +' || (c->>'xp_square') || ' XP.');
      elsif nd.kind = 'pagamento' then
        ev := ev || jsonb_build_object('t','pagamento','msg','Parou no Dia de pagamento.');
      elsif nd.kind = 'carta' then
        card := floor(random() * 6)::int;
        if card = 0 then
          extra_coins := extra_coins + (c->>'card_coins_win')::int;
          ev := ev || jsonb_build_object('t','carta','msg','Carta da sorte: um treinador agradecido te deu ' || (c->>'card_coins_win') || ' moedas.');
        elsif card = 1 then
          amt := (c->>'card_coins_lose')::int; if cls = 'clerigo' then amt := ceil(amt / 2.0); end if;
          extra_coins := extra_coins - amt;
          ev := ev || jsonb_build_object('t','carta','msg','Carta do azar: sua mochila rasgou e você perdeu ' || amt || ' moedas.');
        elsif card = 2 then
          w := public.walk(me.id, (c->>'card_steps')::int); sal := sal + (w->>'salary')::int;
          ev := ev || jsonb_build_object('t','carta','msg','Carta da sorte: atalho secreto! Avançou ' || (c->>'card_steps') || ' casas.');
        elsif card = 3 then
          amt := (c->>'card_steps')::int; if cls = 'clerigo' then amt := ceil(amt / 2.0); end if;
          if public.is_shielded(me.id) then ev := ev || jsonb_build_object('t','carta','msg','Carta do azar: você ia se perder, mas a Bênção te guiou.');
          else perform public.go_back(me.id, amt); ev := ev || jsonb_build_object('t','carta','msg','Carta do azar: você se perdeu e voltou ' || amt || ' casas.');
          end if;
        elsif card = 4 then
          update characters set hints = hints + 1 where id = me.id;
          ev := ev || jsonb_build_object('t','carta','msg','Carta da sorte: ganhou 1 Dica.');
        else
          update characters set retries = retries + 1 where id = me.id;
          ev := ev || jsonb_build_object('t','carta','msg','Carta da sorte: ganhou 1 Tente outra vez.');
        end if;
      elsif nd.kind = 'raio' then
        select ch.* into other from characters ch join board_nodes b on b.id = ch.node
         where ch.arrived_rank is null and ch.user_id <> uid order by b.dist asc limit 1 for update of ch;
        my_dist := (select dist from board_nodes where id = landed);
        if other.id is null or (select dist from board_nodes where id = other.node) >= my_dist then
          ev := ev || jsonb_build_object('t','raio','msg','A tempestade caiu longe: ninguém está à sua frente.');
        elsif public.is_shielded(other.id) then
          ev := ev || jsonb_build_object('t','raio','msg','Você chamou um raio em ' || other.name || ', mas a Bênção dele o protegeu.');
        elsif other.class::text = 'mago' and random() * 100 < (c->>'mago_resist_pct')::int then
          ev := ev || jsonb_build_object('t','raio','msg','Você chamou um raio em ' || other.name || ', mas a magia dele desviou.');
        else
          perform public.go_back(other.id, (c->>'storm_push')::int);
          ev := ev || jsonb_build_object('t','raio','msg','Você chamou um raio no líder ' || other.name || ': ele voltou ' || (c->>'storm_push') || ' casas.');
          insert into event_log(user_id, kind, message) values (uid, 'raio', me.name || ' derrubou um raio no líder ' || other.name || '.');
          if other.user_id = leader then
            extra_coins := extra_coins + bounty;
            ev := ev || jsonb_build_object('t','procurado','msg','Recompensa: você acertou o procurado e ganhou ' || bounty || ' moedas.');
          end if;
        end if;
      elsif nd.kind = 'troca' then
        my_dist := (select dist from board_nodes where id = landed);
        select ch.* into other from characters ch join board_nodes b on b.id = ch.node
         where ch.arrived_rank is null and ch.user_id <> uid and b.dist < my_dist order by b.dist desc limit 1 for update of ch;
        if other.id is not null and public.is_shielded(other.id) then
          ev := ev || jsonb_build_object('t','troca','msg','O portal tentou te trocar com ' || other.name || ', mas a Bênção dele impediu.');
        elsif other.id is not null then
          select node, path into tmp_node, tmp_path from characters where id = me.id;
          update characters set node = other.node, path = other.path where id = me.id;
          update characters set node = tmp_node, path = tmp_path where id = other.id;
          ev := ev || jsonb_build_object('t','troca','msg','Portal! Você trocou de lugar com ' || other.name || '.');
          insert into event_log(user_id, kind, message) values (uid, 'troca', me.name || ' trocou de lugar com ' || other.name || ' pelo portal.');
        else
          ev := ev || jsonb_build_object('t','troca','msg','O portal não encontrou ninguém à sua frente.');
        end if;
      elsif nd.kind in ('mina', 'desafio', 'ladrao', 'fonte', 'treinador', 'alvo') then
        -- casas novas (arquivo 42) e treinadores (arquivo 43)
        hx := public.house_extra(me.id, nd.kind, modes, dodge);
        ev := ev || coalesce(hx->'ev', '[]'::jsonb);
        extra_coins := extra_coins + coalesce((hx->>'coins')::int, 0);
        extra_xp := extra_xp + coalesce((hx->>'xp')::int, 0);
        sal := sal + coalesce((hx->>'sal')::int, 0);
      end if;
    end if;

    -- 3) encontro na mesma casa vira duelo
    select * into me from characters where id = me.id;
    select ch.* into other from characters ch join board_nodes b on b.id = ch.node
     where ch.user_id <> uid and ch.node = me.node and ch.arrived_rank is null and b.kind not in ('inicio','castelo')
       -- com o líder, só há encontro se o outro for o melhor da última rodada (se o líder for o melhor, nada acontece)
       and (leader is null or (ch.user_id <> leader and uid <> leader) or (champ is not null and champ <> leader and champ in (uid, ch.user_id)))
     order by random() limit 1 for update of ch;
    if other.id is not null then
      chance := 50 + (me.level - other.level) * (c->>'duel_level_factor')::int
                   + case when cls = 'guerreiro' then (c->>'guerreiro_duel_bonus')::int else 0 end
                   - case when other.class::text = 'guerreiro' then (c->>'guerreiro_duel_bonus')::int else 0 end;
      chance := chance
        + case when exists (select 1 from villages where user_id = uid and arena_level > 0) then coalesce((c->>'arena_bonus')::int, 10) else 0 end
        - case when exists (select 1 from villages where user_id = other.user_id and arena_level > 0) then coalesce((c->>'arena_bonus')::int, 10) else 0 end;
      chance := greatest(25, least(75, chance));
      if random() * 100 < chance then
        steal := least((c->>'duel_coins')::int, other.coins);
        update characters set coins = coins - steal where id = other.id;
        perform public.go_back(other.id, (c->>'duel_push')::int);
        extra_coins := extra_coins + steal;
        ev := ev || jsonb_build_object('t','duelo','msg','Encontro com ' || other.name || ': você venceu o duelo, ganhou ' || steal || ' moedas' || case when public.is_shielded(other.id) then '.' else ' e empurrou o rival.' end);
        if other.user_id = leader then
          extra_coins := extra_coins + bounty;
          ev := ev || jsonb_build_object('t','procurado','msg','Recompensa: você venceu o procurado e ganhou ' || bounty || ' moedas.');
        end if;
        insert into event_log(user_id, kind, message) values (uid, 'duelo', me.name || ' venceu um duelo contra ' || other.name || '.');
      else
        steal := least((c->>'duel_coins')::int, greatest(0, me.coins + extra_coins));
        update characters set coins = coins + steal where id = other.id;
        extra_coins := extra_coins - steal;
        perform public.go_back(me.id, (c->>'duel_push')::int);
        ev := ev || jsonb_build_object('t','duelo','msg','Encontro com ' || other.name || ': você perdeu o duelo e ' || steal || ' moedas' || case when public.is_shielded(me.id) then ', mas a Bênção te manteve no lugar.' else ' e voltou ' || (c->>'duel_push') || ' casas.' end);
        insert into event_log(user_id, kind, message) values (uid, 'duelo', other.name || ' defendeu sua casa contra ' || me.name || '.');
      end if;
    end if;

    -- 4) pedágio da pousada de outro jogador
    select * into me from characters where id = me.id;
    select * into prop from properties where node = me.node and owner <> uid for update;
    if prop.node is not null then
      toll := greatest((c->>'property_min_toll')::int, ceil(prop.price * (c->>'property_toll_pct')::numeric / 100)::int);
      toll := least(toll, greatest(0, me.coins + extra_coins + base * (c->>'coins_per_step')::int));
      if toll > 0 then
        extra_coins := extra_coins - toll;
        update characters set coins = coins + toll where user_id = prop.owner;
        update properties set tolls_earned = tolls_earned + toll where node = prop.node;
        ev := ev || jsonb_build_object('t','pousada','msg','Pedágio na pousada de ' || (select name from characters where user_id = prop.owner) || ': -' || toll || ' moedas.');
        insert into event_log(user_id, kind, message) values (uid, 'pousada', me.name || ' pagou ' || toll || ' moedas de pedágio na pousada de ' || (select name from characters where user_id = prop.owner) || '.');
      end if;
    end if;
    if sal > 0 then ev := ev || jsonb_build_object('t','pagamento','msg','Dia de pagamento: +' || sal || ' moedas de salário' ||
      case when uid = public.snorlax_id() then ' (10% a menos por ser o Snorlax da rodada).' else '.' end); end if;
    msg := public.check_arrival(me.id);
    if msg is not null then ev := ev || jsonb_build_object('t','castelo','msg', msg); end if;
  end if;

  xp_gain := base * (c->>'xp_per_step')::int + (c->>'xp_daily_bonus')::int + extra_xp;
  if (select xp_buff_until from characters where id = me.id) >= today then
    xp_gain := round(xp_gain * coalesce((c->>'boss_xp_mult')::numeric, 1.5))::int;
    ev := ev || jsonb_build_object('t','buff','msg','Bênção do lendário derrotado: XP aumentado.');
  end if;
  coin_gain := base * (c->>'coins_per_step')::int + extra_coins;
  select * into me from characters where id = me.id;
  new_level := public.level_for_xp(me.xp_total + xp_gain);
  if new_level > old_level then
    ev := ev || jsonb_build_object('t','nivel','msg','Subiu para o nível ' || new_level || '!');
    insert into event_log(user_id, kind, message) values (uid, 'nivel', me.name || ' chegou ao nível ' || new_level || '.');
  end if;
  update characters set xp_total = xp_total + xp_gain, level = new_level,
         coins = greatest(0, coins + coin_gain), last_move_date = greatest(coalesce(last_move_date, _d), _d)
   where id = me.id returning * into me;

  insert into daily_moves(user_id, move_date, modes, base_steps, roll, bonus_steps, skill_steps, from_node, to_node, xp_gained, coins_gained, events, recovered)
  values (uid, _d, modes, base, roll, bonus, skill_steps, from_node, me.node, xp_gain, coin_gain + sal, ev, _recovery);
  insert into event_log(user_id, kind, message, data)
  values (uid, 'andou', me.name || ' andou ' || total || ' casas' || case when _recovery then ' recuperando o dia ' || to_char(_d, 'DD/MM') else '' end || '.', jsonb_build_object('steps', total));

  return jsonb_build_object('date', _d, 'recovery', _recovery, 'base', base, 'roll', roll, 'bonus', bonus, 'skill', skill_steps, 'total', total, 'modes', modes,
    'from', from_node, 'to', me.node, 'path', to_jsonb(me.path), 'events', ev,
    'xp', xp_gain, 'coins', coin_gain + sal, 'level', new_level, 'leveled', new_level > old_level);
end $$;

-- efeitos das casas novas (versão do 46 + item na Fonte e HM rara contra treinadores)
create or replace function public.house_extra(_cid uuid, _kind text, _modes jsonb, _dodge boolean) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare c jsonb := public.casas_cfg(); me characters; ev jsonb := '[]'::jsonb; coins int := 0; sal int := 0; w jsonb; hd jsonb; amt int; stone text; solved int; ball text;
begin
  select * into me from characters where id = _cid;
  if _kind = 'mina' then
    -- Mina de pedras: chance de achar uma pedra de evolução; senão, umas moedas
    if random() * 100 < (c->>'mina_stone_pct')::numeric then
      stone := public.random_stone();
      insert into bag_items(user_id, item, qty) values (me.user_id, stone, 1) on conflict (user_id, item) do update set qty = bag_items.qty + 1;
      ev := ev || jsonb_build_object('t', 'mina', 'msg', '⛏️ Mina de pedras: você achou uma ' || public.stone_name(stone) || '! Ela foi para a bolsa.');
      insert into event_log(user_id, kind, message) values (me.user_id, 'mina', me.name || ' achou uma ' || public.stone_name(stone) || ' na mina!');
    else
      coins := (c->>'mina_coins')::int;
      ev := ev || jsonb_build_object('t', 'mina', 'msg', '⛏️ Mina de pedras: nenhuma pedra hoje, mas você juntou ' || coins || ' moedas de minério.');
    end if;
  elsif _kind = 'desafio' then
    -- Casa do Desafio: premia quem acertou os 4 modos do dia; quem errou algum volta casas
    select count(*) into solved from jsonb_each(_modes) x where (x.value->>'solved')::boolean;
    if solved >= 4 then
      coins := (c->>'desafio_coins')::int;
      w := public.walk(_cid, (c->>'desafio_steps')::int); sal := (w->>'salary')::int;
      ev := ev || jsonb_build_object('t', 'desafio', 'msg', '🎯 Casa do Desafio: você acertou os 4 modos! Ganhou ' || coins || ' moedas e avançou ' || (c->>'desafio_steps') || ' casas.');
    else
      amt := (c->>'desafio_back')::int;
      if _dodge then ev := ev || jsonb_build_object('t', 'desafio', 'msg', '🎯 Casa do Desafio: você não acertou os 4 modos, mas o Atalho te livrou da punição.');
      elsif public.is_shielded(_cid) then ev := ev || jsonb_build_object('t', 'desafio', 'msg', '🎯 Casa do Desafio: você não acertou os 4 modos, mas a Bênção te segurou.');
      else
        perform public.go_back(_cid, amt);
        ev := ev || jsonb_build_object('t', 'desafio', 'msg', '🎯 Casa do Desafio: só acertou ' || solved || ' de 4 modos. Voltou ' || amt || ' casas.');
      end if;
    end if;
  elsif _kind = 'ladrao' then
    -- Ladrão de estrada: leva uma parte das moedas (o Clérigo perde metade)
    amt := least((c->>'ladrao_max')::int, floor(me.coins * (c->>'ladrao_pct')::numeric / 100))::int;
    if me.class::text = 'clerigo' then amt := ceil(amt / 2.0)::int; end if;
    if amt <= 0 then ev := ev || jsonb_build_object('t', 'ladrao', 'msg', '🦹 Um ladrão de estrada revirou sua mochila, mas não achou nenhuma moeda. Ufa!');
    elsif _dodge then ev := ev || jsonb_build_object('t', 'ladrao', 'msg', '🦹 Um ladrão de estrada apareceu, mas o Atalho te tirou do caminho dele.');
    elsif public.is_shielded(_cid) then ev := ev || jsonb_build_object('t', 'ladrao', 'msg', '🦹 Um ladrão de estrada tentou te roubar, mas a Bênção te protegeu.');
    else
      coins := -amt;
      ev := ev || jsonb_build_object('t', 'ladrao', 'msg', '🦹 Ladrão de estrada! Ele levou ' || amt || ' moedas da sua mochila.');
    end if;
  elsif _kind = 'fonte' then
    -- Fonte das Bolas: ganha uma Great Ball ou, com sorte, uma Ultra Ball
    ball := case when random() * 100 < (c->>'fonte_ultra_pct')::numeric then 'ultra_ball' else 'great_ball' end;
    insert into bag_items(user_id, item, qty) values (me.user_id, ball, 1) on conflict (user_id, item) do update set qty = bag_items.qty + 1;
    ev := ev || jsonb_build_object('t', 'fonte', 'msg', '⛲ Fonte das Bolas: saiu uma ' || case when ball = 'ultra_ball' then 'Ultra Ball' else 'Great Ball' end || ' para a sua bolsa!');
    w := public.item_drop(me.user_id, 'fonte');
    if w is not null then ev := ev || w; end if;
  elsif _kind = 'treinador' then
    -- Treinador no caminho: batalha automática 3x3 contra um treinador do jogo (arquivo 43)
    w := public.npc_fight(_cid);
    ev := ev || coalesce(w->'ev', '[]'::jsonb); coins := coins + coalesce((w->>'coins')::int, 0);
    -- vitória contra o treinador: chance rara de achar uma HM (arquivo 47)
    if coalesce((select won from npc_fights where id = (w->'ev'->0->>'fight')::bigint), false) then
      hd := public.hm_drop(me.user_id, 'npc');
      if hd is not null then ev := ev || hd; end if;
    end if;
  elsif _kind = 'alvo' then
    -- fim do caminho da Caçada (arquivo 46): o primeiro a chegar tenta capturar; os outros voltam
    ev := ev || public.hunt_arrive(_cid);
  end if;
  return jsonb_build_object('ev', ev, 'coins', coins, 'sal', sal);
end $$;

-- ---------- permissões ----------
revoke execute on function public.bt_item_check(jsonb, int, uuid, text, int), public.bt_item_apply(jsonb, int, uuid, text, int), public.item_drop(uuid, text), public.hm_drop(uuid, text),
  public.hm_shortcut(uuid, int), public.gift_bag_ok(text), public.bt_resolve(uuid), public.house_extra(uuid, text, jsonb, boolean) from public, anon, authenticated;
revoke execute on function public.battle_act(uuid, int, text, int, text), public.mon_teach(uuid, text, int), public.admin_pk_item_set(text, int), public.items_cfg() from public, anon;
grant execute on function public.battle_act(uuid, int, text, int, text), public.mon_teach(uuid, text, int), public.admin_pk_item_set(text, int), public.items_cfg(),
  public.pk_buy(text, int), public.do_move(date, boolean) to authenticated;
